acceptance_cmd:
set -eu
./ops/backlog.py add --help 2>&1 | grep -Fq -- '--stage' || { echo "FAIL: add has no --stage path"; exit 1; }
./ops/backlog.py add --help 2>&1 | grep -Fq -- '--queue' || { echo "FAIL: staged add cannot be pointed at a scratch queue, so this criterion cannot run hermetically"; exit 1; }
Q=$(mktemp -t backlog_add_queue.XXXXXX)
trap 'if [ -e "$Q" ]; then unlink "$Q"; fi' EXIT
before=$(git status --porcelain | wc -l | tr -d ' ')
OUT=$(./ops/backlog.py add --stage --queue "$Q" --stream IMP --date 2026-01-01 --source 'probe' --category tool --severity low --brief 'probe' --scope 'probe' --detail 'probe' --json) || { echo "FAIL: staged add returned non-zero"; exit 1; }
after=$(git status --porcelain | wc -l | tr -d ' ')
test "$before" = "$after" || { echo "FAIL: staged add dirtied the working tree ($before -> $after)"; exit 1; }
ID=$(printf '%s' "$OUT" | uv run --no-project --python 3.13 python -c 'import json,sys; print(json.load(sys.stdin)["entry"]["id"])')
test -n "$ID" || { echo "FAIL: staged add did not report an id"; exit 1; }
test ! -f "docs/runbook/backlog/$ID.json" || { echo "FAIL: staged add wrote the store file immediately ($ID)"; exit 1; }
grep -Fq "$ID" "$Q" || { echo "FAIL: staged add did not append the row to the queue"; exit 1; }
(./ops/backlog.py list --help 2>&1; ./ops/backlog.py validate --help 2>&1) | grep -Eqi 'pending|staged|queue' || { echo "FAIL: no entrypoint reports how many staged adds are still unmaterialised — forgetting to anchor stays invisible"; exit 1; }
test -x ops/tests/test_backlog_add_stage.sh || { echo "FAIL: no executable negative control proving the staged path can fail"; exit 1; }
echo OK
